import { expect, test, uniqueName } from "../../fixtures";
import type { APIRequestContext } from "@playwright/test";

// Builds a vendor whose three documents are extracted and submitted. The insurance expiry decides its lowest confidence.
async function vendorInReview(member: APIRequestContext, insuranceExpiry: string): Promise<string> {
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Review Vendor"), category: "services", contact_email: "billing@example.com" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = (await created.json()) as { id: string };

  const documents: [string, string][] = [
    ["w9", "Legal Name: Acme Supply\nTax ID: 123456789\nBusiness Type: LLC\n"],
    ["insurance_certificate", `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: 2000000\nExpiry Date: ${insuranceExpiry}\n`],
    ["contract", "Counterparty: Acme Supply\nEffective Date: 2025-01-01\nExpiry Date: 2099-12-31\n"],
  ];
  for (const [kind, text] of documents) {
    const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: { kind, file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) } },
    });
    expect(upload.status(), await upload.text()).toBe(201);
  }

  // Extraction runs in the background after each upload.
  await expect
    .poll(
      async () => {
        const res = await member.get(`/api/vendors/${vendor.id}/documents`);
        const list = (await res.json()) as { status: string }[];
        return list.length === 3 && list.every((d) => d.status === "extracted");
      },
      { timeout: 30_000 },
    )
    .toBe(true);

  const submit = await member.post(`/api/vendors/${vendor.id}/submit`);
  expect(submit.status(), await submit.text()).toBe(200);
  return vendor.id;
}

test("the review queue shows lowest confidence first", { tag: "@REV-03" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const reviewer = await apiAs("reviewer");
  const shaky = await vendorInReview(member, "next spring");
  const confident = await vendorInReview(member, "2099-12-31");

  // Act
  const response = await reviewer.get("/api/review-queue");
  expect(response.status(), await response.text()).toBe(200);
  const queue = (await response.json()) as { vendor_id: string; lowest_confidence: number }[];
  const ids = queue.map((item) => item.vendor_id);

  // Assert: the parallel suite shares the queue, so compare our two vendors by position.
  expect(ids).toContain(shaky);
  expect(ids).toContain(confident);
  expect(ids.indexOf(shaky), "low-confidence vendor is ahead of the confident one").toBeLessThan(ids.indexOf(confident));
  expect(queue[ids.indexOf(shaky)].lowest_confidence).toBe(0.40);
  expect(queue[ids.indexOf(confident)].lowest_confidence).toBe(0.95);
});
